# Source for q/ae-valves.js: Valve disease, Prosthetic valves, Endocarditis.
# Cutoffs follow 2017 ASE valve regurgitation guidance and 2020 ACC/AHA valve guidelines.
V="Valve disease"; P="Prosthetic valves"; E="Endocarditis"
Q=[
# --- Aortic stenosis ---
(V,"The most common cause of aortic stenosis in older adults in developed countries is:","Calcific (degenerative) disease of a trileaflet valve",["Rheumatic heart disease","Endocarditis","Supravalvular membrane"],"Calcium builds up from the base of the cusps, stiffening them. Rheumatic AS usually comes with mitral valve disease.","F"),
(V,"A patient in their 40s with aortic stenosis most likely has:","A bicuspid aortic valve",["Senile calcific degeneration of a trileaflet valve","Carcinoid disease","Lambl's excrescences"],"Bicuspid valves calcify and narrow decades earlier than trileaflet valves.","F"),
(V,"Severe aortic stenosis by ACC/AHA criteria includes a peak velocity of at least:","4.0 m/s",["2.0 m/s","3.0 m/s","5.5 m/s"],"Severe: Vmax ≥ 4 m/s, mean gradient ≥ 40 mmHg, AVA ≤ 1.0 cm². Very severe: Vmax ≥ 5 m/s or mean gradient ≥ 60 mmHg.","F"),
(V,"A mean gradient of at least which value suggests severe aortic stenosis?","40 mmHg",["10 mmHg","20 mmHg","100 mmHg"],"Moderate AS has a mean gradient of 20 to 39 mmHg.","F"),
(V,"An aortic valve area of 0.8 cm² is consistent with:","Severe aortic stenosis",["Mild aortic stenosis","Moderate aortic stenosis","A normal valve"],"Normal AVA is 3 to 4 cm². Mild over 1.5, moderate 1.0 to 1.5, severe 1.0 cm² or less.","F"),
(V,"The dimensionless index (LVOT VTI ÷ aortic valve VTI) in severe aortic stenosis is usually:","Less than 0.25",["Greater than 0.5","Exactly 1.0","Greater than 0.8"],"Because it doesn't need the LVOT diameter, the dimensionless index avoids the biggest error in continuity.","F"),
(V,"Indexed aortic valve area suggesting severe AS is:","0.6 cm²/m² or less",["1.5 cm²/m² or less","2.0 cm²/m² or less","0.1 cm²/m² only"],"Indexing to body surface area helps in very small or very large patients.","C"),
(V,"To find the highest aortic stenosis velocity, the sonographer should:","Use CW Doppler from several windows: apical, right parasternal, suprasternal and subcostal",["Use PW Doppler only from the apical view","Use one window only","Use color Doppler peak velocity"],"The jet direction varies. Missing the highest velocity underestimates severity. A non-imaging CW probe helps at the right parasternal window.","F"),
(V,"Low-flow, low-gradient aortic stenosis with reduced EF is evaluated further with:","Low-dose dobutamine stress echo",["Exercise treadmill without imaging","Agitated saline","Valsalva maneuver"],"If the valve area stays small as flow rises, AS is truly severe. If the area increases, it is pseudo-severe AS caused by weak LV contraction.","F"),
(V,"Pseudo-severe aortic stenosis on dobutamine echo shows:","The valve area increasing above 1.0 cm² as flow rises, with the gradient staying under 40 mmHg",["The gradient rising above 40 mmHg with an area under 1.0 cm²","No change in stroke volume","Severe MR appearing"],"The valve was only partly opened by a weak ventricle. Lack of contractile reserve (stroke volume rise under 20%) is a separate, poor-prognosis finding.","C"),
(V,"A bicuspid aortic valve is best identified in the parasternal short-axis view by:","Two cusps opening in a 'fish-mouth' shape in systole",["Three cusps forming a 'Mercedes-Benz' sign","A doming mitral valve","A single coronary artery"],"A raphe can make a bicuspid valve look trileaflet when closed, so judge it in systole.","F"),
(V,"A bicuspid aortic valve is associated with:","Coarctation of the aorta and dilation of the ascending aorta",["Ebstein anomaly","Mitral stenosis only","Carcinoid syndrome"],"Always check the aortic root, ascending aorta and arch (suprasternal view) for coarctation.","F"),
(V,"On M-mode, a bicuspid aortic valve may show:","An eccentric closure line",["A central closure line","A 'hockey-stick' leaflet","Systolic anterior motion"],"An eccentricity index above 1.5 suggests a bicuspid valve.","C"),
(V,"Chronic severe aortic stenosis causes which LV change?","Concentric hypertrophy from pressure overload",["Eccentric dilation from volume overload","A thin LV wall","Right ventricular dilation only"],"The LV thickens to overcome the high afterload.","F"),
(V,"Supravalvular aortic stenosis is associated with:","Williams syndrome",["Marfan syndrome","Turner syndrome","Down syndrome"],"The narrowing is above the sinotubular junction. Williams syndrome also includes hypercalcemia and characteristic facial features.","C"),
(V,"Fixed subaortic stenosis is most often caused by:","A discrete fibromuscular membrane below the aortic valve",["Calcific cusps","Systolic anterior motion of the mitral valve","A bicuspid valve"],"The membrane causes turbulent flow below the valve and can damage the valve, causing AR.","F"),
(V,"Which CW Doppler shape suggests dynamic LVOT obstruction rather than fixed valvular AS?","Late-peaking, dagger-shaped",["Early-peaking, rounded","Holosystolic and symmetric","Diastolic only"],"Obstruction in HCM worsens as the LV gets smaller in late systole.","F"),
# --- Aortic regurgitation ---
(V,"Common causes of aortic regurgitation include:","Aortic root dilation, bicuspid valve, endocarditis and rheumatic disease",["Mitral annular calcification","Carcinoid syndrome only","Pulmonary embolism"],"AR comes from either cusp disease or dilation of the root and annulus.","F"),
(V,"High-frequency fluttering of the anterior mitral leaflet on M-mode is a sign of:","Aortic regurgitation",["Mitral stenosis","Hypertrophic cardiomyopathy","Pericardial effusion"],"The regurgitant jet strikes the anterior mitral leaflet in diastole.","F"),
(V,"Premature closure of the mitral valve on M-mode suggests:","Acute severe aortic regurgitation",["Mild mitral stenosis","Normal diastolic function","Pulmonary hypertension"],"LV diastolic pressure rises so quickly that it exceeds LA pressure before atrial contraction. It is a medical emergency.","C"),
(V,"Holodiastolic flow reversal in the proximal descending aorta indicates:","Severe aortic regurgitation",["Mild aortic stenosis","Normal aortic flow","Coarctation"],"Reversal seen in the abdominal aorta is even more specific for severe AR.","F"),
(V,"An AR pressure half-time of less than 200 ms suggests:","Severe aortic regurgitation",["Mild aortic regurgitation","Aortic stenosis","Normal aortic valve"],"Aortic and LV diastolic pressures equalize quickly. A PHT over 500 ms suggests mild AR. PHT is also affected by LV compliance.","F"),
(V,"An AR vena contracta width of 0.6 cm or more suggests:","Severe aortic regurgitation",["Mild aortic regurgitation","Moderate aortic stenosis","Nothing; vena contracta is not used for AR"],"Mild AR has a vena contracta under 0.3 cm.","F"),
(V,"An AR jet width that is 65% or more of the LVOT width suggests:","Severe aortic regurgitation",["Mild aortic regurgitation","Aortic stenosis","Normal valve"],"Under 25% suggests mild AR. Measure jet width just below the valve in PLAX.","F"),
(V,"Chronic severe aortic regurgitation causes the LV to become:","Dilated (eccentric hypertrophy) from volume overload",["Small and thick only","Normal size","Restrictive"],"The LV accepts extra blood every diastole and dilates. LV end-systolic size helps decide timing of surgery.","F"),
(V,"Regurgitant fraction suggesting severe AR or MR is:","50% or more",["10%","20%","30%"],"Regurgitant volume of 60 mL or more and EROA of 0.3 cm² (AR) or 0.4 cm² (primary MR) or more also suggest severe regurgitation.","F"),
# --- Mitral stenosis ---
(V,"The most common cause of mitral stenosis worldwide is:","Rheumatic heart disease",["Mitral annular calcification","Congenital parachute mitral valve","Endocarditis"],"In older patients in developed countries, calcific (degenerative) MS from annular calcification is increasing.","F"),
(V,"In rheumatic mitral stenosis, the anterior leaflet in PLAX classically shows:","Diastolic doming, a 'hockey-stick' appearance",["Systolic anterior motion","Prolapse into the LA","Fluttering"],"Commissural fusion restricts the tips while the body of the leaflet still bulges, creating the hockey-stick shape.","F"),
(V,"In the parasternal short-axis view, rheumatic mitral stenosis shows a:","'Fish-mouth' orifice from commissural fusion",["Normal oval orifice","Cleft anterior leaflet","Three-leaflet valve"],"Planimetry of the smallest orifice at the leaflet tips gives the mitral valve area.","F"),
(V,"Severe mitral stenosis by ACC/AHA criteria is a valve area of:","1.5 cm² or less",["4.0 cm² or less","2.5 cm² or less","3.0 cm² or more"],"Normal MVA is 4 to 6 cm². Very severe MS is 1.0 cm² or less.","F"),
(V,"A mitral pressure half-time of 150 ms or more suggests:","Severe mitral stenosis",["Normal mitral valve","Mitral regurgitation","Aortic stenosis"],"MVA = 220 ÷ PHT; 220 ÷ 150 ≈ 1.5 cm².","F"),
(V,"Mitral PHT can be unreliable for valve area in all of these EXCEPT:","Stable sinus rhythm with no other valve disease",["Immediately after balloon valvuloplasty","Significant aortic regurgitation","Markedly abnormal LV compliance"],"PHT depends on the pressures and compliance of both chambers, not just the orifice.","C"),
(V,"Mean mitral gradient depends strongly on:","Heart rate and flow across the valve",["Only the valve area","LVOT diameter","The patient's height"],"Faster heart rates shorten diastole and raise the gradient. Always report the heart rate with the gradient.","F"),
(V,"A common complication of mitral stenosis is:","Left atrial enlargement with atrial fibrillation and thrombus in the LA appendage",["LV hypertrophy","Aortic dissection","Ventricular septal rupture"],"Blood stagnates in the enlarged LA. TEE is best for excluding LA appendage thrombus.","F"),
(V,"Mitral stenosis can lead to pulmonary hypertension because:","Raised LA pressure is transmitted back to the pulmonary veins and arteries",["It reduces RV pressure","It increases LV pressure","It narrows the pulmonary valve"],"Estimate PA systolic pressure from the TR velocity in every MS study.","F"),
(V,"The Wilkins score for balloon mitral valvuloplasty grades:","Leaflet mobility, thickening, calcification and subvalvular thickening",["Ejection fraction, LV size, LA size and RV size","Heart rate, rhythm, gradient and PHT","Aortic and pulmonary valve disease"],"Each item scores 1 to 4. A total of 8 or less favors a good valvuloplasty result.","C"),
(V,"On M-mode, rheumatic mitral stenosis shows:","A reduced E-F slope and anterior motion of the posterior leaflet in diastole",["An increased E-F slope","Systolic anterior motion","Fluttering of the anterior leaflet"],"Fused commissures pull the posterior leaflet forward with the anterior one.","C"),
(V,"Mitral annular calcification (MAC) is most common in:","Older adults and patients with chronic kidney disease",["Young athletes","Children with Down syndrome","Patients with carcinoid"],"MAC usually involves the posterior annulus and can cause mild MS or MR.","F"),
# --- Mitral regurgitation and MVP ---
(V,"Primary (degenerative) mitral regurgitation is caused by:","Disease of the valve itself, such as prolapse or flail leaflet",["LV dilation pulling the leaflets apart","Atrial fibrillation alone","Aortic stenosis"],"Secondary (functional) MR comes from LV or annular remodeling with structurally normal leaflets.","F"),
(V,"Secondary (functional) MR from ischemic cardiomyopathy is caused by:","LV dilation and papillary muscle displacement tethering the leaflets",["Myxomatous leaflet thickening","Chordal rupture","Rheumatic fusion"],"The leaflets can't close fully because they are pulled toward the apex.","F"),
(V,"Mitral valve prolapse is diagnosed when a leaflet moves above the annular plane by more than:","2 mm in the parasternal long-axis view",["2 mm in the apical four-chamber view only","10 mm in any view","0.5 mm in PSAX"],"The annulus is saddle-shaped, so A4C can overcall prolapse. Use PLAX.","F"),
(V,"Prolapse of the posterior mitral leaflet usually produces an MR jet directed:","Anteriorly, toward the interatrial septum",["Posteriorly, toward the lateral LA wall","Centrally","Into the LV"],"The jet goes away from the diseased leaflet. Anterior leaflet prolapse sends the jet posteriorly.","C"),
(V,"A flail mitral leaflet is recognized when:","The leaflet tip points into the left atrium in systole",["The leaflet domes in diastole","The leaflet is thickened but closes normally","The leaflet flutters in diastole"],"Flail leaflets usually come from ruptured chordae and cause severe MR.","F"),
(V,"Eccentric MR jets that hug the atrial wall are often underestimated by color jet area because of:","The Coanda effect",["Aliasing","Pressure recovery","Reverberation"],"Wall-hugging jets lose energy and look smaller. Use vena contracta, PISA and other signs.","F"),
(V,"An MR vena contracta of 0.7 cm or more suggests:","Severe mitral regurgitation",["Mild mitral regurgitation","Mitral stenosis","Normal valve"],"Mild MR has a vena contracta under 0.3 cm.","F"),
(V,"Systolic flow reversal in the pulmonary veins suggests:","Severe mitral regurgitation",["Normal LA pressure","Mitral stenosis","Mild aortic regurgitation"],"The MR jet pushes blood back into the pulmonary veins during systole.","F"),
(V,"A dense, triangular, early-peaking CW Doppler MR signal suggests:","Severe MR with rapid rise in LA pressure",["Mild MR","Mitral stenosis","Normal MR"],"Early peaking (the V-wave cutoff sign) shows LA pressure rising quickly.","C"),
(V,"An effective regurgitant orifice area (EROA) of 0.4 cm² or more in primary MR suggests:","Severe MR",["Mild MR","Moderate MS","Normal valve"],"In secondary MR, an EROA of 0.4 cm² or more also indicates severe MR under current guidelines.","F"),
(V,"LV dP/dt from the MR jet is calculated using the time for velocity to rise from:","1 m/s to 3 m/s",["0 to 1 m/s","3 to 5 m/s","2 to 4 m/s"],"Pressure change = 4(3²) − 4(1²) = 32 mmHg. dP/dt = 32 ÷ time. Normal is over 1,200 mmHg/s; under 800 mmHg/s means severe LV dysfunction.","C"),
(V,"An MR jet rises from 1 to 3 m/s in 20 ms. What is the LV dP/dt?","1,600 mmHg/s",["640 mmHg/s","32 mmHg/s","800 mmHg/s"],"dP/dt = 32 mmHg ÷ 0.020 s = 1,600 mmHg/s, which is normal.","C"),
(V,"The M-mode finding in mitral valve prolapse is:","Late-systolic posterior 'hammock' bowing of the leaflets",["Fluttering in diastole","A flat E-F slope","Systolic anterior motion"],"The leaflets sag back toward the LA in mid to late systole.","C"),
(V,"Systolic anterior motion (SAM) of the mitral valve is associated with:","Hypertrophic obstructive cardiomyopathy",["Mitral stenosis","Aortic regurgitation","Dilated cardiomyopathy"],"SAM pulls the leaflet into the LVOT, causing obstruction and a posteriorly directed MR jet.","F"),
# --- Tricuspid and pulmonic ---
(V,"The most common cause of significant tricuspid regurgitation is:","Functional TR from RV and annular dilation",["Rheumatic disease","Carcinoid syndrome","Ebstein anomaly"],"Pulmonary hypertension and left heart disease dilate the RV and annulus.","F"),
(V,"Systolic flow reversal in the hepatic veins suggests:","Severe tricuspid regurgitation",["Mild tricuspid regurgitation","Tricuspid stenosis","Normal right heart"],"The regurgitant jet pushes blood back into the IVC and hepatic veins.","F"),
(V,"A TR vena contracta of 0.7 cm or more suggests:","Severe tricuspid regurgitation",["Mild tricuspid regurgitation","Pulmonic stenosis","Normal valve"],"Other severe TR signs: a dense triangular CW signal, dilated RA and RV and a plethoric IVC.","F"),
(V,"Carcinoid heart disease typically affects:","The tricuspid and pulmonic valves, which become thickened, retracted and fixed",["The aortic valve only","The mitral valve only","The coronary arteries"],"Serotonin from liver metastases reaches the right heart; the lungs inactivate it before it reaches the left heart.","F"),
(V,"Ebstein anomaly is identified by:","Apical displacement of the septal tricuspid leaflet",["A bicuspid aortic valve","A cleft mitral leaflet","Pulmonary vein stenosis"],"Displacement of more than 8 mm/m² relative to the mitral annulus 'atrializes' part of the RV.","F"),
(V,"Pulmonic stenosis is most often:","Congenital, with a doming valve and post-stenotic pulmonary artery dilation",["Rheumatic","Calcific in the elderly","Caused by endocarditis"],"Severe PS: peak velocity over 4 m/s, peak gradient over 64 mmHg.","F"),
(V,"A trace of tricuspid or pulmonic regurgitation in a healthy adult is:","A normal, physiologic finding",["Always pathologic","A sign of endocarditis","A sign of carcinoid"],"Small amounts of right-sided regurgitation are common and are useful for estimating pressures.","F"),
(V,"Severe pulmonic regurgitation is commonly seen after:","Surgical repair of tetralogy of Fallot",["Mitral valve repair","Aortic valve replacement","Closure of an ASD"],"Transannular patch repairs often leave a free-flowing pulmonic valve, leading to RV dilation.","C"),
(V,"Rheumatic heart disease most commonly affects which valves, in order?","Mitral, then aortic, then tricuspid",["Tricuspid, then pulmonic","Aortic only","Pulmonic, then mitral"],"Rheumatic changes include commissural fusion and thickened, shortened chordae.","F"),
# --- Prosthetic valves ---
(P,"The most commonly implanted mechanical valve type today is the:","Bileaflet tilting-disc valve",["Caged-ball valve","Single tilting-disc valve","Homograft"],"Bileaflet valves (such as the St. Jude type) have two semicircular discs and three orifices.","F"),
(P,"The main disadvantage of a mechanical valve is:","The need for lifelong anticoagulation",["Short durability","Frequent calcification within 5 years","It cannot be used in the mitral position"],"Mechanical valves last a long time but can thrombose without warfarin.","F"),
(P,"The main disadvantage of a bioprosthetic valve is:","Structural degeneration over 10 to 20 years",["Lifelong anticoagulation is always required","It cannot be imaged","It has no flow orifice"],"Tissue valves avoid long-term anticoagulation but wear out, more quickly in younger patients.","F"),
(P,"Small, symmetrical regurgitant jets seen within a normal mechanical valve are:","Normal 'washing' jets designed into the valve",["Paravalvular leaks","Signs of endocarditis","Signs of thrombus"],"Washing jets clean the hinges. They are brief, low-volume and come from inside the sewing ring.","F"),
(P,"A paravalvular leak is regurgitation that occurs:","Outside the sewing ring, between the ring and native tissue",["Through the center of a normal valve","Through the leaflets of a bioprosthesis only","In the pulmonary veins"],"It can come from suture dehiscence or endocarditis and may cause hemolysis.","F"),
(P,"A 'rocking' motion of a prosthetic valve suggests:","Dehiscence of the sewing ring",["Normal function","Prosthesis-patient mismatch","Pannus"],"A large part of the ring has separated from the annulus, usually with severe paravalvular regurgitation.","C"),
(P,"Why is TEE often needed to assess a mitral prosthesis?","Shadowing from the prosthesis on TTE hides the left atrium and MR jets",["TTE cannot show the LV","TEE uses a lower frequency","The mitral valve cannot be seen on TTE"],"From the apical window, the prosthesis lies in front of the LA. TEE views the LA from behind.","F"),
(P,"Prosthetic valve thrombus differs from pannus in that thrombus usually:","Appears soft, larger, more recent and linked to low anticoagulation",["Is dense, fibrous and grows slowly over years","Never causes obstruction","Only occurs in bioprostheses"],"Pannus is fibrous tissue ingrowth around the ring. Distinguishing them matters because thrombus may respond to thrombolysis.","C"),
(P,"Prosthesis-patient mismatch (PPM) occurs when:","A normally working valve is too small for the patient's body size",["A valve is implanted upside down","Endocarditis destroys the valve","The valve has a paravalvular leak"],"In the aortic position, an indexed EOA of 0.65 cm²/m² or less is severe mismatch.","F"),
(P,"In a prosthetic aortic valve, which finding suggests obstruction?","Dimensionless index under 0.25 and acceleration time over 100 ms",["Dimensionless index over 0.35","Acceleration time under 80 ms","Peak velocity under 2 m/s"],"A rounded, late-peaking jet with a low DVI points to obstruction rather than high flow.","C"),
(P,"Doppler can overestimate gradients across a bileaflet mechanical valve because:","The small central orifice produces a localized high velocity, and pressure recovery occurs",["The valve has only one orifice","The discs absorb sound","Mechanical valves never have gradients"],"CW may record the high central jet, which does not represent the whole valve.","C"),
(P,"Transcatheter aortic valve replacement (TAVR) involves:","A bioprosthetic valve inside a stent frame, delivered by catheter",["A mechanical caged-ball valve placed surgically","Repair of the native leaflets","A homograft root replacement"],"After TAVR, echo looks for paravalvular leak, gradients and complications such as pericardial effusion.","F"),
(P,"A homograft valve is:","A human donor valve, often an aortic root",["A pig valve","A mechanical valve","A synthetic polymer valve"],"Homografts are often used in endocarditis because of their resistance to infection.","C"),
(P,"A caged-ball valve (Starr-Edwards type) produces which echo appearance?","A ball moving within a cage, with marked reverberation and shadowing",["Two thin discs","Three thin cusps in a stent","No artifact"],"Older ball valves are bulky and highly reflective. Flow goes around the ball.","C"),
(P,"Every prosthetic valve study should record:","Heart rate, blood pressure, valve type and size",["Only the peak velocity","The patient's weight only","No baseline data"],"Gradients vary with heart rate and flow. Comparison with the post-operative baseline study is key.","F"),
(P,"A mitral annuloplasty ring is used to:","Reduce the annulus size in mitral valve repair",["Replace the leaflets","Close an ASD","Support the aortic root"],"After repair, assess residual MR, the mean gradient (for stenosis) and any SAM.","F"),
(P,"Hemolysis after valve surgery is most often associated with:","A paravalvular leak",["A normal bioprosthesis","Pannus","A homograft"],"Red cells are damaged as they are forced at high velocity through a small paravalvular channel.","C"),
# --- Endocarditis ---
(E,"Vegetations in endocarditis typically attach to the:","Upstream (low-pressure) side of the valve",["Downstream side of the valve","Aortic wall only","Pericardium"],"For the mitral and tricuspid valves this is the atrial side; for the aortic and pulmonic valves, the ventricular side.","F"),
(E,"On the aortic valve, a vegetation is most likely found on the:","Ventricular side of the cusps",["Aortic side of the cusps","Left atrial side","Pulmonary artery"],"It is the side facing the regurgitant jet and lower pressure.","F"),
(E,"Typical echo features of a vegetation include:","An irregular, mobile mass that moves independently of the valve",["A smooth, fixed, calcified nodule","A thin, linear strand on the aortic side of an old valve","Uniform valve thickening without a mass"],"Vegetations oscillate with high-frequency motion and are attached on the upstream side.","F"),
(E,"Compared with TTE, TEE for suspected endocarditis is:","More sensitive, especially for prosthetic valves and abscesses",["Less sensitive","Never needed","Only useful for the tricuspid valve"],"TEE sensitivity for vegetations is over 90%, versus much lower for TTE.","F"),
(E,"In intravenous drug users, endocarditis most commonly affects the:","Tricuspid valve",["Aortic valve","Mitral valve","Pulmonic valve"],"Injected material and organisms reach the right heart first.","F"),
(E,"A perivalvular abscess appears on echo as:","An echolucent or echodense area in the annulus or aortic root, beside the valve",["A thin line on the aortic cusp","A small pericardial effusion","A dilated LV"],"Abscesses are serious and often need surgery. TEE is much better than TTE for finding them.","F"),
(E,"A vegetation larger than about 10 mm is associated with:","Higher risk of embolism",["Lower risk of embolism","No added risk","Only valve stenosis"],"Large, mobile vegetations, especially on the mitral valve, are more likely to break off.","F"),
(E,"Which organism is known for causing aggressive, rapidly destructive endocarditis?","Staphylococcus aureus",["Viridans streptococci","Lactobacillus","Candida only in healthy patients"],"Staph aureus often causes abscess, perforation and acute valve failure.","F"),
(E,"Libman-Sacks endocarditis is:","A non-infective verrucous endocarditis seen in systemic lupus erythematosus",["A bacterial endocarditis in drug users","Endocarditis caused by fungi","Normal aging change"],"Small, sterile vegetations form, often on the mitral valve.","C"),
(E,"Nonbacterial thrombotic (marantic) endocarditis is associated with:","Advanced cancer and hypercoagulable states",["Intravenous drug use","Rheumatic fever","Bicuspid aortic valve"],"Sterile platelet-fibrin vegetations form on valves and can embolize.","C"),
(E,"Lambl's excrescences are:","Thin, filamentous strands on the aortic valve closure line, common with aging",["Infective vegetations","Abscesses","Tumors"],"They are usually benign and must not be mistaken for vegetations.","C"),
(E,"Leaflet perforation from endocarditis is suggested by:","A regurgitant jet passing through the body of the leaflet rather than the coaptation line",["A central jet at the coaptation point","No regurgitation","Diastolic doming"],"Color Doppler across the leaflet body is a key clue. TEE confirms it.","C"),
(E,"Echo is a major criterion in the Duke criteria for endocarditis when it shows:","A vegetation, abscess or new dehiscence of a prosthetic valve",["A small pericardial effusion","Mild LV dilation","Trace TR"],"Other major criteria include typical organisms in repeated blood cultures.","F"),
(E,"A pseudoaneurysm of the mitral-aortic intervalvular fibrosa in endocarditis appears as:","A pulsatile echo-free space between the aortic root and the anterior mitral leaflet that fills in systole",["A solid mass in the LV","A thin strand on the valve","A dilated pulmonary artery"],"Color Doppler shows flow into the cavity. It can rupture into the LA, forming a fistula.","C"),
(E,"New severe regurgitation in a patient with fever and positive blood cultures suggests:","Valve destruction from endocarditis",["Normal aging","Pulmonary embolism","Pericarditis"],"Look closely for vegetations, perforation and abscess, usually with TEE.","F"),
(E,"Prosthetic valve endocarditis is best evaluated with:","TEE",["TTE alone","M-mode only","Chest X-ray"],"Shadowing on TTE hides vegetations and abscesses around prostheses.","F"),
(E,"Which valve lesion carries the highest risk for developing endocarditis?","A prosthetic heart valve",["Trace physiologic TR","A normal mitral valve","Mild MAC without regurgitation"],"Prosthetic valves, previous endocarditis and certain congenital lesions are the highest-risk conditions.","F"),
]
